## Data Management

### Network Considerations
```typescript
import NetInfo from '@react-native-community/netinfo';

// Check network connectivity
const [isConnected, setIsConnected] = useState(true);

useEffect(() => {
  const unsubscribe = NetInfo.addEventListener(state => {
    setIsConnected(state.isConnected ?? false);
  });

  return unsubscribe;
}, []);

// Handle offline scenarios
const fetchData = async () => {
  if (!isConnected) {
    // Use cached data or show offline message
    return getCachedData();
  }

  try {
    return await apiCall();
  } catch (error) {
    // Fallback to cached data on error
    return getCachedData();
  }
};
```

### Local Storage
```typescript
import AsyncStorage from '@react-native-async-storage/async-storage';

// Store data locally
const storeData = async (key: string, value: any) => {
  try {
    await AsyncStorage.setItem(key, JSON.stringify(value));
  } catch (error) {
    console.error('Failed to store data:', error);
  }
};

// Retrieve data
const getData = async (key: string) => {
  try {
    const value = await AsyncStorage.getItem(key);
    return value ? JSON.parse(value) : null;
  } catch (error) {
    console.error('Failed to retrieve data:', error);
    return null;
  }
};
```

### Secure Storage
```typescript
import * as Keychain from 'react-native-keychain';

// Store sensitive data securely
const storeCredentials = async (username: string, password: string) => {
  try {
    await Keychain.setCredentials('myApp', username, password);
  } catch (error) {
    console.error('Failed to store credentials:', error);
  }
};

// Retrieve sensitive data
const getCredentials = async () => {
  try {
    const credentials = await Keychain.getCredentials('myApp');
    if (credentials) {
      return {
        username: credentials.username,
        password: credentials.password,
      };
    }
  } catch (error) {
    console.error('Failed to retrieve credentials:', error);
  }
  return null;
};
```

