  });

  // Test workflow
  await page.goto('/vehicles');
  await expect(page.locator('tbody tr').filter({ hasText: 'Test Truck' }))
    .toBeVisible();

  // Cleanup
  await deleteTestVehicle(request, vehicle.id);
